test('undo is a new change, and refuses to lose a newer edit', () => {
  const h = new History();
  h.change('r', 'ana', { a: 1, b: 1 });
  h.change('r', 'ana', { a: 2 });
  h.change('r', 'ben', { b: 2 });
  const u = h.undo('r', 2, 'ana');
